"""Writes stack.env with freshly generated random secrets.

Contains NO personal credential: the ChatGPT login is made later, inside the
codex-proxy container, and is stored only in the codex_auth volume.
Refuses to overwrite an existing stack.env.
"""
import base64
import pathlib
import secrets
import sys

out = pathlib.Path(__file__).with_name("stack.env")
if out.exists():
    sys.exit(f"{out} already exists; delete it first if you really want new secrets.")


def b64() -> str:
    return base64.b64encode(secrets.token_bytes(32)).decode()


lines = [
    "# Generated by gen_env.py - random local-only secrets, nothing personal.",
    "",
    "# --- LLM: SupoClip thinks this is an Ollama server; it is the codex-proxy gateway",
    "LLM=ollama:gpt-6-luna",
    "OLLAMA_BASE_URL=http://codex-proxy:10531/v1",
    "OLLAMA_API_KEY=local-placeholder",
    "RERANK_LLM=",
    "",
    "# --- transcription: local Whisper (no AssemblyAI key needed)",
    "TRANSCRIPTION_PROVIDER=whisper",
    "WHISPER_MODEL_SIZE=small",
    "BACKEND_CPU_ONLY=true",
    "",
    "# --- app",
    "SELF_HOST=true",
    "FRONTEND_PORT=3107",
    "NEXT_PUBLIC_APP_URL=http://localhost:3107",
    "BETTER_AUTH_URL=http://localhost:3107",
    "ALLOW_UNSIGNED_BACKEND_AUTH=false",
    "COMPOSE_DOCKER_CLI_BUILD=1",
    "DOCKER_BUILDKIT=1",
    "",
    "# --- secrets (random)",
    f"BETTER_AUTH_SECRET={b64()}",
    f"BACKEND_AUTH_SECRET={b64()}",
    f"APP_SETTINGS_ENCRYPTION_KEY={b64()}",
    f"REDIS_PASSWORD={secrets.token_hex(16)}",
    "",
]
out.write_text("\n".join(lines), encoding="utf-8")
print(f"wrote {out} ({len(lines)} lines); secrets are not printed.")
